import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/reportdesigner/verwaltung-einstellungen-interne-text.png",_=JSON.parse('{"title":"E-Mail-Standardtexte festlegen","description":"","frontmatter":{"title":"E-Mail-Standardtexte festlegen","source_pageid":924,"source_revision":6582},"headers":[],"relativePath":"reporting/reportdesigner/interne-texte-verwaltung-einstellungen.md","filePath":"reporting/reportdesigner/interne-texte-verwaltung-einstellungen.md"}'),l={name:"reporting/reportdesigner/interne-texte-verwaltung-einstellungen.md"};function s(d,e,o,g,p,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="e-mail-standardtexte-festlegen" tabindex="-1">E-Mail-Standardtexte festlegen <a class="header-anchor" href="#e-mail-standardtexte-festlegen" aria-label="Permalink to &quot;E-Mail-Standardtexte festlegen&quot;">​</a></h1><p>Legen Sie die Texte fest, die SchILD-NRW 3 beim Versand von Notendateien, Kennwörtern und Reportdateien vorbelegt.</p><p><strong>Standardtexte festlegen</strong></p><p><a href="/bilder/reportdesigner/verwaltung-einstellungen-interne-text.png"><img src="'+a+'" alt="Setzen der Texten für den Emailversand." loading="lazy"></a></p><p><em>Setzen der Texten für den Emailversand.</em></p><ol><li>Öffnen Sie <strong>Verwaltung → Einstellungen</strong> und dort den Bereich <strong>Interne Text</strong>.</li><li>Hinterlegen Sie die E-Mail-Inhalte für <strong>Notendateien</strong>, <strong>Passwörter an Lehrkräfte</strong> und den <strong>Versand von Reportdateien</strong>.</li><li>Verwenden Sie diese Texte beim jeweiligen Versand als vorbelegten Inhalt und passen Sie sie bei Bedarf im Versanddialog an.</li></ol><p>Die erzeugten Inhalte können als Anhang versendet werden; bei Reportausgaben wird beispielsweise das Dokument an die E-Mail angehängt.</p><p>Für den Einzelversand lesen Sie <a href="/reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.html">Einen Report per E-Mail versenden und teilen</a>, für schülerindividuelle Ausgaben <a href="/reporting/reportdesigner/serien-e-mail-versand.html">Reportausgaben als Serien-E-Mail versenden</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Interne_Texte_(Verwaltung_Einstellungen)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6582.</p>',10)])])}const m=n(l,[["render",s]]);export{_ as __pageData,m as default};
